rsql select group_concat(k.key, ',') from log_players lp, json_each(more('log_players', lp._more), '$.person') k where lp._row = (select min(_row) from log_players where level = 'NFL' and season = 2034 and person__player__position = 'IOL')
rsql select group_concat(k.key, ',') from log_players lp, json_each(more('log_players', lp._more), '$.person.player') k where lp._row = (select min(_row) from log_players where level = 'NFL' and season = 2034 and person__player__position = 'IOL')
rsql select substr(json_extract(more('log_players', lp._more), '$.person.player.attributes'),1,300) from log_players lp where lp._row = (select min(_row) from log_players where level = 'NFL' and season = 2034 and person__player__position = 'IOL')
